import json
import time
import urllib.request
import urllib.error


_TEMPLATES = {
    'software': {
        'meta-category': 'misc',
        'description': 'Software object',
        'uuid': 'b1b5dc0e-73fe-443c-8d9d-0e208de3951e',
        'version': '1',
    },
    'vulnerability': {
        'meta-category': 'vulnerability',
        'description': 'Vulnerability object',
        'uuid': '81650945-f186-437b-8945-9f31715d32da',
        'version': '12',
    },
    'file': {
        'meta-category': 'file',
        'description': 'File object',
        'uuid': '688c46fb-5edb-40a3-8273-1af7923e2215',
        'version': '25',
    },
}


def http_post(url, body, extra_headers=None, timeout=15):
    try:
        data = json.dumps(body).encode()
        h = {'Content-Type': 'application/json', 'Accept': 'application/json'}
        if extra_headers:
            h.update(extra_headers)
        req = urllib.request.Request(url, data=data, headers=h, method='POST')
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return json.loads(r.read()), None
    except urllib.error.HTTPError as e:
        snippet = ''
        try:
            snippet = e.read().decode()[:160]
        except Exception:
            pass
        return {}, 'HTTP ' + str(e.code) + ': ' + snippet
    except Exception as e:
        return {}, str(e)


def _auth(key):
    return {'Authorization': key}


def add_object(eid, name, attrs, url, key):
    rows = [
        {'object_relation': a['r'], 'type': a.get('t', 'text'), 'value': str(a['v'])}
        for a in attrs if a.get('v') not in (None, '', [])
    ]
    if not rows:
        return None
    tmpl = _TEMPLATES.get(name, {})
    body = {
        'name': name,
        'meta-category': tmpl.get('meta-category', 'misc'),
        'description': tmpl.get('description', name),
        'template_uuid': tmpl.get('uuid', ''),
        'template_version': tmpl.get('version', '1'),
        'force': 1,
        'Attribute': rows,
    }
    _, err = http_post(url + '/objects/add/' + eid, body, extra_headers=_auth(key))
    return err


def add_attr(eid, atype, value, category, url, key):
    if value in (None, '', 0):
        return None
    _, err = http_post(
        url + '/attributes/add/' + eid,
        {'Attribute': {'type': atype, 'category': category, 'value': str(value)}},
        extra_headers=_auth(key),
    )
    return err


def run(raw, misp_url, misp_key):
    if isinstance(raw, str):
        raw = json.loads(raw)

    batch   = raw.get('research_batch', {})
    fw_list = raw.get('firmware', [])
    if not fw_list:
        return json.dumps({'error': 'firmware list empty or missing'})

    errors  = []
    created = []

    for fw in fw_list:
        vendor  = fw.get('vendor', 'Unknown')
        product = fw.get('product', 'Unknown')
        version = fw.get('version', '')
        vulns   = fw.get('vulnerabilities', [])

        scores = [float(v.get('cvss_score') or 0) for v in vulns]
        m  = max(scores, default=0)
        tl = 1 if m >= 9 else 2 if m >= 7 else 3 if m >= 4 else 4

        r, err = http_post(
            misp_url + '/events',
            {'Event': {'info': 'Firmware research -- ' + vendor + ' ' + product + ' ' + version,
                       'analysis': 1, 'threat_level_id': tl, 'distribution': 0}},
            extra_headers=_auth(misp_key),
        )
        eid = str(r.get('Event', {}).get('id', ''))
        if err:
            errors.append('create_event(' + vendor + ' ' + product + '): ' + err)
        if not eid:
            continue

        err = add_object(eid, 'software', [
            {'r': 'name',    'v': product},
            {'r': 'version', 'v': version},
            {'r': 'vendor',  'v': vendor},
        ], misp_url, misp_key)
        if err:
            errors.append('software_obj(' + vendor + ' ' + product + '): ' + err)

        err = add_attr(eid, 'sha256',   fw.get('firmware_sha256', ''), 'Artifacts dropped', misp_url, misp_key)
        if err:
            errors.append('sha256(' + vendor + '): ' + err)
        err = add_attr(eid, 'filename', fw.get('firmware_file',   ''), 'Artifacts dropped', misp_url, misp_key)
        if err:
            errors.append('filename(' + vendor + '): ' + err)

        has_cve = False
        for vuln in vulns:
            cve_id = vuln.get('cve')
            rid    = vuln.get('research_id') or cve_id or 'UNKNOWN'

            if cve_id:
                err = add_attr(eid, 'vulnerability', cve_id, 'External analysis', misp_url, misp_key)
                if err:
                    errors.append('vuln_attr(' + rid + '): ' + err)
                has_cve = True

            err = add_object(eid, 'vulnerability', [
                {'r': 'id',                  'v': rid},
                {'r': 'summary',             'v': vuln.get('title', '')},
                {'r': 'description',         'v': vuln.get('description', '')},
                {'r': 'cvss-score',          'v': vuln.get('cvss_score'), 't': 'float'},
                {'r': 'cwe',                 'v': vuln.get('cwe', '')},
                {'r': 'cve',                 'v': cve_id or ''},
                {'r': 'state',               'v': vuln.get('disclosure_status', 'private')},
                {'r': 'exploit-complexity',  'v': vuln.get('exploit_complexity', '')},
                {'r': 'operational-impact',  'v': vuln.get('operational_impact', '')},
                {'r': 'exposure',            'v': vuln.get('exposure', '')},
                {'r': 'poc-available',       'v': str(vuln.get('poc_available', False))},
            ], misp_url, misp_key)
            if err:
                errors.append('vuln_obj(' + rid + '): ' + err)

            if vuln.get('affected_binary'):
                err = add_object(eid, 'file', [
                    {'r': 'path',   'v': vuln['affected_binary']},
                    {'r': 'sha256', 'v': vuln.get('binary_sha256', '')},
                ], misp_url, misp_key)
                if err:
                    errors.append('file_obj(' + rid + '): ' + err)

            if vuln.get('trigger_port'):
                err = add_attr(eid, 'port', str(vuln['trigger_port']), 'Network activity', misp_url, misp_key)
                if err:
                    errors.append('port(' + rid + '): ' + err)

        if has_cve:
            http_post(misp_url + '/events/enrichEvent/' + eid, {'cve': True}, extra_headers=_auth(misp_key))
            time.sleep(10)

        created.append({'vendor': vendor, 'product': product,
                        'version': version, 'misp_event_id': eid})

    return json.dumps({
        'success':     len(created) > 0,
        'batch':       batch,
        'created':     created,
        'error_count': len(errors),
        'errors':      errors,
    }, indent=2)


items = json.loads("""$exec""")
print(run(items, '$MISP_URL', '$MISP_API_KEY'))
